  @Eq (Option Nat) (Etna.Committee.switchTarget s h) (@Option.some Nat t) →
    @LT.lt Nat instLTNat (@OfNat.ofNat Nat (nat_lit 0) (instOfNatNat (nat_lit 0))) t

