    @Eq (Option Etna.Committee.Record) (Etna.Committee.lookup st.records t) (@Option.none Etna.Committee.Record) →
      @Eq (Option Etna.Committee.Record) (Etna.Committee.authority s st (Etna.Committee.H s t))
